context.expression:
# ONE entry for every section: the save dialog's Section row picks where
# it lands. Offered when ANY section could take the node - the union of
# what the panel's can_save answers, kept literal so a right-click never
# depends on importing the package.
n = kwargs.get("node", None)
if n is None:
    return False
# Mirrors CopLibrary.ITEM_CONTEXTS: every context the Nodes section saves.
KINDS = ("Sop", "Cop", "Lop", "Dop", "Top", "Chop", "Object", "Vop")
try:
    if n.type().category().name() in KINDS:
        return True
except AttributeError:
    pass
for name in ("snippet", "vexpression", "kernelcode", "python", "code"):
    if n.parm(name) is not None:
        return True
try:
    for parm in n.parms():
        t = parm.parmTemplate()
        if t.type() == hou.parmTemplateType.Ramp and t.parmType() == hou.rampParmType.Color:
            return True
except Exception:
    pass
return False

scriptItem.labelExpression:
try:
    from amaze import branding
    _APP = branding.APP_NAME
except Exception:
    _APP = "Amaze"

return "Save to " + _APP
